import test from 'node:test';
import assert from 'node:assert';
import { throttle } from './solution.js';

test('fires immediately on first call', async () => {
  let calls = 0;
  const t = throttle(() => calls++, 100);
  t();
  assert.strictEqual(calls, 1);
});

test('ignores calls within window', async () => {
  let calls = 0;
  const t = throttle(() => calls++, 200);
  t(); t(); t();
  assert.strictEqual(calls, 1);
});

test('allows call after window expires', async () => {
  let calls = 0;
  const t = throttle(() => calls++, 50);
  t();
  await new Promise(r => setTimeout(r, 100));
  t();
  assert.strictEqual(calls, 2);
});

reference_solution:
export function throttle(fn, limitMs) {
  let last = -Infinity;
  return (...args) => {
    const now = Date.now();
    if (now - last >= limitMs) {
      last = now;
      fn(...args);
    }
  };
}
